def learned(category, metric, group="all", stat="typical"):
    """what REAL models of a category do, learned from dissected references (kit library inspect -> kit learn):
    rbx.learned("firearm", "bevel_size_mm", "role:slide") -> the typical value, stat="low" / "high" its range; None
    when nothing is known yet (`lune run kit learned show firearm` lists every metric and group)"""
    refs = os.path.join(REPO, "kit", "refs")
    if refs not in sys.path:
        sys.path.insert(0, refs)
    import learn  # noqa: PLC0415

    return learn.learned(category, metric, group, stat)


