def _args():
    return set(sys.argv[sys.argv.index("--") + 1 :]) if "--" in sys.argv else set()


def _optimizing_built_master(name):
    """`kit optimize <name>` (--optimize) of a master whose build exists (build/models/<name>.manifest.json, stage
    master) -> True"""
    if "--optimize" not in _args():
        return False
    try:
        with open(os.path.join(EXPORTS, f"{name}.manifest.json"), encoding="utf-8") as fh:
            return json.load(fh).get("stage") == "master"
    except (OSError, ValueError, AttributeError):
        return False


def _build_script():
    """the build_*.py being run (sys.argv first: the worker and kit asset pass it), else the Asset's caller"""
    script = next((x for x in sys.argv if x.endswith(".py") and os.path.basename(x).startswith("build_")), None)
    return script if script and os.path.isfile(script) else _caller_script()


def _png_side(path):
    """a PNG file's larger side in pixels, read off its header - None when it is no PNG or cannot be read"""
    import struct  # noqa: PLC0415

    try:
        with open(path, "rb") as fh:
            head = fh.read(24)
    except OSError:
        return None
    if len(head) < 24 or head[:8] != b"\x89PNG\r\n\x1a\n":
        return None
    return max(struct.unpack(">II", head[16:24]))


def _made_by_kit_make(script):
    """kit make writes 'MADE BY kit make' on the first line of the script it makes"""
    try:
        with open(script, encoding="utf-8") as fh:
            return "MADE BY kit make" in fh.readline()
    except (OSError, TypeError, UnicodeDecodeError):
        return False


def _grandfathered(name, script):
    """the owner's 7+ / keep piece whose build script is byte for byte the one he judged (board/grandfathered.json:
    asset + sha1) -> its entry, else None. Any edit changes the sha1: the piece then builds at its tier, every check"""
    import hashlib  # noqa: PLC0415

    try:
        with open(os.path.join(REPO, "board", "grandfathered.json"), encoding="utf-8") as fh:
            pieces = json.load(fh).get("pieces") or []
        with open(script, "rb") as fh:
            sha = hashlib.sha1(fh.read()).hexdigest()
    except (OSError, ValueError, TypeError, AttributeError):
        return None
    return next((g for g in pieces if g.get("asset") == name and g.get("sha1") == sha), None)


def _brief_tier(name, script):
    """(tier, where it came from) for a script that names no quality=: the brief's quality answer (<name>.brief.md
    beside the script: '- quality: hero ...', the tier kit plan's clock runs on) when it says hero / aaa, else prop
    (prop and complex build at the prop gates)"""
    path = rbx_plan.brief_path(name, script, REPO)
    try:
        brief = rbx_plan.load_brief(path, REPO)
    except (OSError, ValueError, UnicodeDecodeError):
        brief = None
    said = str(((brief or {}).get("answers") or {}).get("quality") or "").lower()
    m = re.search(r"\b(prop|complex|hero|aaa)\b", said)
    if m and m.group(1) in ("hero", "aaa"):
        return m.group(1), f"its brief ({brief['path']}: quality {m.group(1)})"
    return "prop", (f"its brief ({brief['path']}: quality {m.group(1)})" if m and brief else "the default (no brief tier)")


