def studio_view(scene):
    """HONEST colour for lit (Cycles) presentation renders — what the owner and every judge look at. Measured on a
    chart of known albedos under the studio (kit selftest "studio is honest"): AgX at 0 EV rendered 18% grey at 0.58
    (too bright) and halved the saturation of warm colours (chest wood chroma 18 against a true 36 — the "pale pink
    wood"); Khronos PBR Neutral at -0.8 EV puts 18% grey at middle grey (0.46) and keeps base colours true (mean dE
    23 -> 6, wood saturation 39% -> 88%)."""
    vs = scene.view_settings
    try:
        vs.view_transform = "Khronos PBR Neutral"
    except TypeError:  # (Blender < 4.2)
        vs.view_transform = "AgX"
    vs.look = "None"
    vs.exposure = -0.8


def flat_view(scene):
    """Flat / measuring renders (Workbench, silhouettes, the quality score's views): Standard, no exposure shift — a
    studio render before them must never leave its -0.8 EV behind (it would darken what the score measures)."""
    vs = scene.view_settings
    vs.view_transform = "Standard"
    vs.look = "None"
    vs.exposure = 0.0


def cycles_device(scene):
    """Cycles on the GPU when there is one — measured on an RTX 5070: AO bake 0.60 s on CUDA vs 4.99 s on CPU with
    identical pixels; the Bevel normal bake 1.1 s vs 10.6 s (1024 px), NOT identical: within 8/255 inside the UV
    islands (more in the margins), and a CUDA rerun can move ~1 pixel by 1 level — a CPU bake is the exact,
    reproducible one (KIT_CYCLES_DEVICE=CPU). Emission passes run on the CPU anyway (faster, see _bake_pass).
    KIT_CYCLES_DEVICE=CPU|CUDA|OPTIX|HIP|METAL|ONEAPI|AUTO (default AUTO) overrides. The kit runs Blender with
    --factory-startup (no saved preferences), so the device is switched on here, in code, every run.
    -> the device type in use ("CPU" when there is no GPU)."""
    global _DEVICE
    if _DEVICE is None:
        want = os.environ.get("KIT_CYCLES_DEVICE", "AUTO").upper()
        _DEVICE = "CPU"
        if want != "CPU":
            try:
                prefs = bpy.context.preferences.addons["cycles"].preferences
                for kind in ([want] if want != "AUTO" else ["CUDA", "OPTIX", "HIP", "METAL", "ONEAPI"]):
                    try:
                        prefs.compute_device_type = kind
                    except TypeError:
                        continue  # not available on this build / OS
                    prefs.get_devices()
                    if any(d.type == kind for d in prefs.devices):
                        for d in prefs.devices:
                            d.use = d.type == kind
                        _DEVICE = kind
                        break
            except Exception:  # noqa: BLE001 — device selection never fails a build: CPU always works
                _DEVICE = "CPU"
        print(f"kit: Cycles device {_DEVICE}")
    scene.cycles.device = "CPU" if _DEVICE == "CPU" else "GPU"
    return _DEVICE


def _rot(rot):
    rx, ry, rz = (math.radians(v) for v in rot)
    # CFrame.Angles(rx, ry, rz) == Rx * Ry * Rz
    return Matrix.Rotation(rx, 4, "X") @ Matrix.Rotation(ry, 4, "Y") @ Matrix.Rotation(rz, 4, "Z")


def _local(pos, rot):
    return Matrix.Translation(Vector(pos)) @ _rot(rot)


def _file_bytes(path):
    """a file's bytes (repo-relative or absolute; b"" when it is not there: the build says so elsewhere)"""
    try:
        with open(path if os.path.isabs(path) else os.path.join(REPO, path), "rb") as fh:
            return fh.read()
    except OSError:
        return b""


def _read_mask_bpy(path):
    """a picture -> float (H, W, 4) 0..1, row 0 the TOP (rbx_stamps.MASK_READER inside Blender: it has no PIL)"""
    import numpy as np  # noqa: PLC0415

    img = bpy.data.images.load(path, check_existing=False)
    try:
        img.colorspace_settings.name = "Non-Color"
        w, h = img.size
        px = np.empty(w * h * 4, np.float32)
        img.pixels.foreach_get(px)
        return np.flipud(px.reshape(h, w, 4))
    finally:
        bpy.data.images.remove(img)


rbx_stamps.MASK_READER = _read_mask_bpy
